+     if (lib->fd >= 1) {
+       if (ph->core == NULL) {
+         close(lib->fd);
+       }
+       else if (lib->fd != ph->core->exec_fd) {
+         // Prevents double-close in core mode.
+	 // exec_fd would be closed at close_files().
+         close(lib->fd);
+       }
+     }

